import { AlertCircle, CircleCheck, CreditCard, Landmark, Link2, LoaderCircle, Plus, RefreshCw, Save, ShieldCheck, Trash2, Wallet } from "@/components/icons/hugeicons"
import { SettingsFieldRow, SettingsIntegrationRow, SettingsPageHeader, SettingsPanel, SettingsToggleRow } from "@/components/multideck/settings-components"
import { StatusPill } from "@/components/multideck/status-pill"
import { TabsRail } from "@/components/multideck/workflow-components"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Switch } from "@/components/ui/switch"
