export type FinanceSetupTab = "overview" | "systems" | "currencies" | "banks" | "ledger" | "tax" | "documents" | "mappings" | "compliance" | "controls"
type DraftRow = Record<string, unknown> & { _key: string; id?: string; isActive?: boolean }

const financeSetupRouteByTab: Record<FinanceSetupTab, string> = {
  overview: "/finance/administration",
  systems: "/finance/systems",
  currencies: "/finance/currencies",
  banks: "/finance/banks",
  ledger: "/finance/ledger",
  tax: "/finance/tax",
  documents: "/finance/documents",
  mappings: "/finance/mappings",
  compliance: "/finance/compliance",
  controls: "/finance/controls",
}

const today = () => new Date().toISOString().slice(0, 10)
const key = () => crypto.randomUUID()
const asRecord = (value: unknown): Record<string, any> => value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, any> : {}
const text = (value: unknown, fallback = "") => typeof value === "string" ? value : typeof value === "number" && Number.isFinite(value) ? String(value) : fallback
const number = (value: unknown, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback
const bool = (value: unknown, fallback = false) => typeof value === "boolean" ? value : fallback
const rowKey = (row: DraftRow) => row.id || row._key
const activeRows = (rows: Array<Record<string, unknown>>) => rows.filter((row) => row.isActive !== false)

const universalTaxTreatments = [
  ["domestic-standard", "Domestic standard", "domestic_standard", "both"],
  ["reduced-rate", "Reduced rate", "reduced_rate", "both"],
  ["zero-rated", "Zero rated", "zero_rated", "both"],
  ["exempt", "Exempt", "exempt", "both"],
  ["export", "Export", "export", "sales"],
  ["reverse-charge", "Reverse charge", "reverse_charge", "both"],
  ["out-of-scope", "Out of scope", "out_of_scope", "both"],
] as const

const defaultSequences = [
  ["sales-invoice", "Sales invoice", "sl_invoice", "SI-"],
  ["customer-credit", "Customer credit note", "credit_note", "SC-"],
  ["purchase-invoice", "Purchase invoice", "pl_invoice", "PI-"],
  ["supplier-credit", "Supplier credit note", "debit_note", "PC-"],
] as const

function noticeClass(tone: "default" | "danger" | "success" = "default") {
  if (tone === "danger") return "bg-[color-mix(in_srgb,var(--md-red),transparent_90%)] text-[var(--md-red)]"
  if (tone === "success") return "bg-[var(--md-accent-a10)] text-[var(--md-green)]"
  return "bg-[var(--md-surface-soft)] text-[var(--md-text)]"
}

function Notice({ tone = "default", children }: { tone?: "default" | "danger" | "success"; children: ReactNode }) {
  return <div role={tone === "danger" ? "alert" : "status"} className={`grid grid-cols-[auto_1fr] gap-3 rounded-[var(--md-radius-lg)] p-4 text-[13px] leading-5 shadow-[var(--md-shadow-line)] ${noticeClass(tone)}`}><AlertCircle className="mt-0.5 size-4" strokeWidth={1.4} />{children}</div>
}

function FieldLabel({ htmlFor, children }: { htmlFor: string; children: ReactNode }) {
  return <label htmlFor={htmlFor} className="text-[12px] font-medium text-[var(--md-text)]">{children}</label>
}

function Field({ id, label, value, onChange, type = "text", placeholder, disabled = false, ltr = false }: { id: string; label: string; value: string | number; onChange: (value: string) => void; type?: string; placeholder?: string; disabled?: boolean; ltr?: boolean }) {
  return <div className="space-y-2"><FieldLabel htmlFor={id}>{label}</FieldLabel><Input id={id} type={type} value={value} placeholder={placeholder} disabled={disabled} onChange={(event) => onChange(event.target.value)} data-i18n-skip={ltr ? true : undefined} dir={ltr ? "ltr" : undefined} /></div>
}

function SelectField({ id, label, value, onChange, options, disabled = false }: { id: string; label: string; value: string; onChange: (value: string) => void; options: Array<{ value: string; label: string }>; disabled?: boolean }) {
  return <div className="space-y-2"><FieldLabel htmlFor={id}>{label}</FieldLabel><Select value={value || "__none__"} onValueChange={(next) => onChange(next === "__none__" ? "" : next)} disabled={disabled}><SelectTrigger id={id}><SelectValue /></SelectTrigger><SelectContent>{options.map((option) => <SelectItem key={option.value || "__none__"} value={option.value || "__none__"}>{option.label}</SelectItem>)}</SelectContent></Select></div>
}

function RowShell({ title, meta, active = true, onRemove, children }: { title: string; meta?: string; active?: boolean; onRemove: () => void; children: ReactNode }) {
  const { t } = useLanguage()
  return <div className={`px-5 py-4 ${active ? "" : "opacity-60"}`}><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div><p className="text-[13px] font-medium text-[var(--md-ink)]" data-i18n-skip>{title}</p>{meta ? <p className="mt-0.5 text-[11px] text-[var(--md-subtle)]">{meta}</p> : null}</div><Button type="button" size="sm" variant="ghost" onClick={onRemove}><Trash2 className="size-4" />{t(active ? "Disable" : "Remove")}</Button></div>{children}</div>
}

function buildDraft(setup: FinanceSetup, legalEntityId: string): FinanceAdministrationDraft {
  const entity = setup.legalEntities.find((item) => item.LegalEntity_ID === legalEntityId) ?? setup.legalEntities[0]
  const id = entity?.LegalEntity_ID ?? ""
  const administration = setup.administration
  const settings = administration.settings.find((item) => item.FINSET_LegalEntityID === id)
  const localisation = administration.localisations.find((item) => item.FINLocSet_LegalEntityID === id)
  const administrationJson = asRecord(settings?.FINSET_SettingsJSON?.administration)
  const defaultsJson = asRecord(settings?.FINSET_SettingsJSON?.defaults)
  const entityAdministration = asRecord(asRecord(entity?.LegalEntity_SettingsJSON).financeAdministration)
  const baseCurrency = (entity?.LegalEntity_BaseCurrencyCodeSnapshot || settings?.FINSET_BaseCurrencyCode || "GBP").toUpperCase()
  const countryCode = (entity?.LegalEntity_CountryCode || "GB").toUpperCase()
  const preferredLocalisationPack = administration.localisationPacks.find((item) => item.FINLocPack_CountryCode === countryCode)
    ?? administration.localisationPacks.find((item) => item.FINLocPack_Code === "global-v1")
  const existingNominals = administration.nominalAccounts.filter((item) => item.FINNom_LegalEntityID === id)
  const templateNominals = administration.chartTemplateAccounts.filter((item) => item.FINChartTemplate?.FINChartTemplate_Code === "freight-forwarder-v1")
  const existingCurrencies = administration.currencies.filter((item) => item.FINCurSet_LegalEntityID === id)
  const existingTaxes = administration.taxCodes.filter((item) => item.FINTax_LegalEntityID === id)
  const existingJurisdictions = administration.taxJurisdictions.filter((item) => item.FINTaxJur_LegalEntityID === id)
  const existingSequences = administration.numberSequences.filter((item) => item.FINSeq_LegalEntityID === id)
  const existingTerms = administration.paymentTerms.filter((item) => item.FINTerm_LegalEntityID === id)
  const connectionIds = new Set(setup.connections.filter((item) => item.ACCIC_LegalEntityID === id).map((item) => item.ACCIC_ID))

  return {
    organisation: {
      baseCurrencyCode: baseCurrency,
      countryCode,
      taxRegistrationNo: entity?.LegalEntity_VATNumber || localisation?.FINLocSet_TaxRegistrationNo || "",
      reportingBasisCode: localisation?.FINLocSet_ReportingBasisCode || "accrual",
      accountingStandardCode: text(entityAdministration.accountingStandardCode, localisation?.FINLocPack?.FINLocPack_AccountingStandardCode || "IFRS"),
      fiscalYearStartMonth: number(entityAdministration.fiscalYearStartMonth, 1),
      timeZone: text(entityAdministration.timeZone, "Europe/London"),
      localisationPackCode: localisation?.FINLocPack?.FINLocPack_Code || preferredLocalisationPack?.FINLocPack_Code || "global-v1",
      effectiveFrom: localisation?.FINLocSet_EffectiveFrom || today(),
    },
    controls: {
      nativeLedgerEnabled: settings?.FINSET_NativeLedgerEnabled ?? true,
      externalMirrorModeCode: settings?.FINSET_ExternalMirrorModeCode || "optional",
      defaultOperatingModelCode: settings?.FINSET_DefaultOperatingModelCode || "hybrid",
      autoCreateSalesInvoices: settings?.FINSET_AutoCreateSalesInvoices ?? false,
      autoCreatePurchaseAccruals: settings?.FINSET_AutoCreatePurchaseAccruals ?? true,
      autoPostLowRiskItems: settings?.FINSET_AutoPostLowRiskItems ?? false,
      useAccountingDateRules: settings?.FINSET_UseAccountingDateRules ?? true,
      blockLockedPeriodDirectPosting: settings?.FINSET_BlockLockedPeriodDirectPosting ?? true,
      defaultRoeProviderCode: settings?.FINSET_DefaultROEProviderCode || "accounting_provider",
      includeFxInOperationalProfit: settings?.FINSET_IncludeFXInOperationalProfit ?? false,
      requireFinanceReview: bool(administrationJson.requireFinanceReview, true),
      allowOperatorTaxOverride: bool(administrationJson.allowOperatorTaxOverride, false),
      allowOperatorAccountOverride: bool(administrationJson.allowOperatorAccountOverride, false),
      allowBackdatedPosting: bool(administrationJson.allowBackdatedPosting, false),
      postingLockDate: text(administrationJson.postingLockDate),
      exchangeRateSource: text(administrationJson.exchangeRateSource, "approved_manual"),
      exchangeRateOverrideRequiresApproval: bool(administrationJson.exchangeRateOverrideRequiresApproval, true),
      exchangeRatePrecision: number(administrationJson.exchangeRatePrecision, 6),
      allocationTolerance: number(administrationJson.allocationTolerance, 0.01),
      roundingTolerance: number(administrationJson.roundingTolerance, 0.01),
    },
    defaults: {
      salesPaymentTermCode: text(defaultsJson.salesPaymentTermCode, "NET30"),
      purchasePaymentTermCode: text(defaultsJson.purchasePaymentTermCode, "NET30"),
      salesInvoiceSequenceCode: text(defaultsJson.salesInvoiceSequenceCode, "sales-invoice"),
      customerCreditSequenceCode: text(defaultsJson.customerCreditSequenceCode, "customer-credit"),
      purchaseInvoiceSequenceCode: text(defaultsJson.purchaseInvoiceSequenceCode, "purchase-invoice"),
      supplierCreditSequenceCode: text(defaultsJson.supplierCreditSequenceCode, "supplier-credit"),
      salesTaxCode: text(defaultsJson.salesTaxCode, "domestic-standard"),
      purchaseTaxCode: text(defaultsJson.purchaseTaxCode, "domestic-standard"),
    },
    taxSettings: {
      priceIncludesTax: bool(localisation?.FINLocSet_SettingsJSON?.priceIncludesTax, false),
      taxPointRule: text(localisation?.FINLocSet_SettingsJSON?.taxPointRule, "invoice_date"),
      reverseChargeEnabled: bool(localisation?.FINLocSet_SettingsJSON?.reverseChargeEnabled, true),
      localAdviceConfirmed: bool(localisation?.FINLocSet_SettingsJSON?.localAdviceConfirmed, false),
    },
    currencies: (existingCurrencies.length ? existingCurrencies.map((item) => ({ _key: item.FINCurSet_ID, id: item.FINCurSet_ID, code: item.FINCurSet_CurrencyCode, name: item.FINCurSet_Name, decimalPlaces: item.FINCurSet_DecimalPlaces, roundingMethodCode: item.FINCurSet_RoundingMethodCode, toleranceAmount: item.FINCurSet_ToleranceAmount, permittedForQuote: item.FINCurSet_IsPermittedForQuote, permittedForInvoice: item.FINCurSet_IsPermittedForInvoice, isActive: item.FINCurSet_IsActive })) : [{ _key: key(), code: baseCurrency, name: baseCurrency, decimalPlaces: 2, roundingMethodCode: "round_half_up", toleranceAmount: 0.01, permittedForQuote: true, permittedForInvoice: true, isActive: true }]),
    banks: administration.banks.filter((item) => item.FINBank_LegalEntityID === id).map((item) => ({ _key: item.FINBank_ID, id: item.FINBank_ID, code: item.FINBank_Code, name: item.FINBank_Name, currencyCode: item.FINBank_CurrencyCode, institutionName: item.FINBank_InstitutionName || "", accountHolderName: item.FINBank_AccountHolderName || "", accountNumberMasked: item.FINBank_AccountNumberMasked || "", ibanMasked: item.FINBank_IBANMasked || "", sortCodeMasked: item.FINBank_SortCodeMasked || "", bicMasked: item.FINBank_BICMasked || "", accountNumberLast4: "", ibanLast4: "", sortCodeLast4: "", bicLast4: "", countryCode: item.FINBank_CountryCode || countryCode, nominalAccountId: item.FINBank_NominalAccountID || "", isDefault: item.FINBank_IsDefault, allowReceipts: item.FINBank_AllowReceipts, allowPayments: item.FINBank_AllowPayments, isActive: item.FINBank_IsActive })),
    nominalAccounts: (existingNominals.length ? existingNominals.map((item) => ({ _key: item.FINNom_ID, id: item.FINNom_ID, code: item.FINNom_Code, name: item.FINNom_Name, accountTypeCode: item.FINNom_AccountTypeCode, externalMappingHint: item.FINNom_ExternalMappingHint || "", isControlAccount: item.FINNom_IsControlAccount, controlTypeCode: item.FINNom_ControlTypeCode || "", allowManualPosting: item.FINNom_AllowManualPosting, isActive: item.FINNom_IsActive })) : templateNominals.map((item) => ({ _key: key(), code: item.FINChartTemplateAccount_Code, name: item.FINChartTemplateAccount_Name, accountTypeCode: item.FINChartTemplateAccount_TypeCode, externalMappingHint: item.FINChartTemplateAccount_Code, isControlAccount: item.FINChartTemplateAccount_IsControlAccount, controlTypeCode: item.FINChartTemplateAccount_IsControlAccount ? item.FINChartTemplateAccount_Name.toLowerCase().replaceAll(" ", "_") : "", allowManualPosting: !item.FINChartTemplateAccount_IsControlAccount, isActive: true }))),
    taxJurisdictions: (existingJurisdictions.length ? existingJurisdictions.map((item) => ({ _key: item.FINTaxJur_ID, id: item.FINTaxJur_ID, code: item.FINTaxJur_Code, name: item.FINTaxJur_Name, countryCode: item.FINTaxJur_CountryCode, authorityName: item.FINTaxJur_AuthorityName || "", registrationNo: item.FINTaxJur_RegistrationNo || "", effectiveFrom: item.FINTaxJur_EffectiveFrom, effectiveTo: item.FINTaxJur_EffectiveTo || "", isActive: item.FINTaxJur_IsActive })) : [{ _key: key(), code: `${countryCode}-TAX`, name: `${countryCode} tax jurisdiction`, countryCode, authorityName: "", registrationNo: entity?.LegalEntity_VATNumber || "", effectiveFrom: today(), effectiveTo: "", isActive: true }]),
    taxCodes: (existingTaxes.length ? existingTaxes.map((item) => ({ _key: item.FINTax_ID, id: item.FINTax_ID, code: item.FINTax_Code, name: item.FINTax_Name, countryCode: item.FINTax_CountryCode || countryCode, ratePercent: item.FINTax_RatePercent, taxTypeCode: item.FINTax_TaxTypeCode, providerMappingHint: item.FINTax_ProviderMappingHint || "", isRecoverable: item.FINTax_IsRecoverable, isActive: item.FINTax_IsActive, effectiveFrom: item.FINTax_EffectiveFrom, effectiveTo: item.FINTax_EffectiveTo || "", jurisdictionId: item.FINTax_JurisdictionID || "", treatmentCategoryCode: item.FINTax_TreatmentCategoryCode, transactionTypeCode: item.FINTax_TransactionTypeCode, outputNominalId: item.FINTax_OutputNominalID || "", inputNominalId: item.FINTax_InputNominalID || "" })) : universalTaxTreatments.map(([code, name, category, transactionType]) => ({ _key: key(), code, name, countryCode, ratePercent: 0, taxTypeCode: "vat", providerMappingHint: "", isRecoverable: !["exempt", "out-of-scope"].includes(code), isActive: true, effectiveFrom: today(), effectiveTo: "", jurisdictionId: "", treatmentCategoryCode: category, transactionTypeCode: transactionType, outputNominalId: "", inputNominalId: "" }))),
    numberSequences: (existingSequences.length ? existingSequences.map((item) => ({ _key: item.FINSeq_ID, id: item.FINSeq_ID, code: item.FINSeq_Code, name: item.FINSeq_Name, documentTypeCode: item.FINSeq_DocumentTypeCode || "", prefix: item.FINSeq_Prefix, suffix: item.FINSeq_Suffix, nextNumber: item.FINSeq_NextNumber, paddingLength: item.FINSeq_PaddingLength, resetPeriodCode: item.FINSeq_ResetPeriodCode, isActive: item.FINSeq_IsActive })) : defaultSequences.map(([code, name, documentTypeCode, prefix]) => ({ _key: key(), code, name, documentTypeCode, prefix, suffix: "", nextNumber: 1, paddingLength: 6, resetPeriodCode: "never", isActive: true }))),
    paymentTerms: (existingTerms.length ? existingTerms.map((item) => ({ _key: item.FINTerm_ID, id: item.FINTerm_ID, code: item.FINTerm_Code, name: item.FINTerm_Name, days: item.FINTerm_Days, dueDayOfMonth: item.FINTerm_DueDayOfMonth || "", endOfMonth: item.FINTerm_EndOfMonth, isCashAccount: item.FINTerm_IsCashAccount, isActive: item.FINTerm_IsActive })) : [{ _key: key(), code: "NET30", name: "30 days", days: 30, dueDayOfMonth: "", endOfMonth: false, isCashAccount: false, isActive: true }, { _key: key(), code: "CASH", name: "Due immediately", days: 0, dueDayOfMonth: "", endOfMonth: false, isCashAccount: true, isActive: true }]),
    accountMappings: administration.accountMappings.filter((item) => connectionIds.has(item.ACCIAM_ConnectionID)).map((item) => ({ _key: item.ACCIAM_ID, id: item.ACCIAM_ID, connectionId: item.ACCIAM_ConnectionID, directionCode: item.ACCIAM_DirectionCode, localContextCode: item.ACCIAM_LocalContextCode || "", providerAccountId: item.ACCIAM_ProviderAccountID, providerAccountCode: item.ACCIAM_ProviderAccountCode || "", providerAccountName: item.ACCIAM_ProviderAccountName || "", isDefault: item.ACCIAM_IsDefault, isActive: item.ACCIAM_IsActive })),
    chargeMappings: administration.chargeMappings.filter((item) => connectionIds.has(item.ACCICM_ConnectionID)).map((item) => ({ _key: item.ACCICM_ID, id: item.ACCICM_ID, connectionId: item.ACCICM_ConnectionID, localChargeCode: item.ACCICM_LocalChargeCodeSnapshot, directionCode: item.ACCICM_DirectionCode, providerItemId: item.ACCICM_ProviderItemID || "", providerItemCode: item.ACCICM_ProviderItemCode || "", providerItemName: item.ACCICM_ProviderItemName || "", providerAccountId: item.ACCICM_ProviderAccountID || "", isActive: item.ACCICM_IsActive })),
    taxMappings: administration.taxMappings.filter((item) => connectionIds.has(item.ACCITM_ConnectionID)).map((item) => ({ _key: item.ACCITM_ID, id: item.ACCITM_ID, connectionId: item.ACCITM_ConnectionID, localTaxCode: item.ACCITM_LocalTaxCode, localTaxDescription: item.ACCITM_LocalTaxDescription || "", countryCode: item.ACCITM_LocalCountryCode || countryCode, directionCode: item.ACCITM_DirectionCode, providerTaxId: item.ACCITM_ProviderTaxID || "", providerTaxCode: item.ACCITM_ProviderTaxCode, providerTaxName: item.ACCITM_ProviderTaxName || "", taxRatePercent: item.ACCITM_TaxRatePercent ?? "", isActive: item.ACCITM_IsActive })),
  }
}

function completeness(setup: FinanceSetup, draft: FinanceAdministrationDraft, legalEntityId: string) {
  const activeConnection = setup.connections.some((item) => item.ACCIC_LegalEntityID === legalEntityId && item.ACCIC_StatusCode === "active")
  const mirrorMode = text(draft.controls.externalMirrorModeCode, "optional")
  const controls = activeRows(draft.nominalAccounts).filter((item) => item.isControlAccount === true).length
  return [
    { label: "Organisation", ready: /^[A-Z]{3}$/.test(draft.organisation.baseCurrencyCode) && /^[A-Z]{2}$/.test(draft.organisation.countryCode) },
    { label: "Multideck ledger", ready: draft.controls.nativeLedgerEnabled === true },
    { label: "External mirror policy", ready: mirrorMode !== "required" || activeConnection },
    { label: "Currencies", ready: activeRows(draft.currencies).length > 0 },
    { label: "Bank accounts", ready: activeRows(draft.banks).length > 0 },
    { label: "Control accounts", ready: controls >= 6 },
    { label: "Tax treatments", ready: activeRows(draft.taxCodes).length > 0 && draft.taxSettings.localAdviceConfirmed === true },
    { label: "Document numbering", ready: activeRows(draft.numberSequences).length >= 4 },
    { label: "Payment terms", ready: activeRows(draft.paymentTerms).length > 0 },
  ]
}

export function FinanceSetupPage({ navigate, initialTab = "overview", syncFinanceRoute = false }: { navigate: (path: string) => void; initialTab?: FinanceSetupTab; syncFinanceRoute?: boolean }) {
  const { t } = useLanguage()
  const [setup, setSetup] = useState<FinanceSetup | null>(null)
  const [draft, setDraft] = useState<FinanceAdministrationDraft | null>(null)
  const [selectedEntityId, setSelectedEntityId] = useState("")
  const [tab, setTab] = useState<FinanceSetupTab>(initialTab)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [reason, setReason] = useState("")
  const [confirmed, setConfirmed] = useState(false)
  const [companies, setCompanies] = useState<Array<{ name: string; company_name?: string; country?: string; default_currency?: string }>>([])
  const [providerBusy, setProviderBusy] = useState<string | null>(null)
  const [providerForm, setProviderForm] = useState<FinanceConfigurationInput>({ legalEntityId: "", chartTemplateCode: "freight-forwarder-v1", providerCode: "erpnext", externalCompany: "", countryCode: "GB", taxRegistrationNo: "", reportingBasisCode: "accrual", effectiveFrom: today() })
  const baseline = useRef("")

  const load = useCallback(async (preferredEntityId?: string) => {
    setLoading(true); setError(null)
    try {
      const result = await getFinanceSetup()
      setSetup(result)
      const entityId = preferredEntityId && result.legalEntities.some((item) => item.LegalEntity_ID === preferredEntityId) ? preferredEntityId : result.legalEntities[0]?.LegalEntity_ID || ""
      setSelectedEntityId(entityId)
      const nextDraft = buildDraft(result, entityId)
      setDraft(nextDraft); baseline.current = JSON.stringify(nextDraft)
      const entity = result.legalEntities.find((item) => item.LegalEntity_ID === entityId)
      setProviderForm((current) => ({ ...current, legalEntityId: entityId, countryCode: entity?.LegalEntity_CountryCode || nextDraft.organisation.countryCode, taxRegistrationNo: entity?.LegalEntity_VATNumber || "", externalCompany: entity?.preferredExternalCompany || "" }))
      if (result.erpNext.configured) {
        try { setCompanies((await getErpNextCompanies()).companies) } catch (cause) { setError(cause instanceof Error ? cause.message : "ERPNext companies could not be loaded.") }
      } else setCompanies([])
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Finance administration could not be loaded.") } finally { setLoading(false) }
  }, [])

  useEffect(() => { void load() }, [load])
  useEffect(() => { setTab(initialTab) }, [initialTab])

  const setOrganisation = (patch: Partial<FinanceAdministrationDraft["organisation"]>) => setDraft((current) => current ? { ...current, organisation: { ...current.organisation, ...patch } } : current)
  const setControls = (patch: Record<string, string | number | boolean | null>) => setDraft((current) => current ? { ...current, controls: { ...current.controls, ...patch } } : current)
  const setDefaults = (patch: Record<string, string | number | boolean | null>) => setDraft((current) => current ? { ...current, defaults: { ...current.defaults, ...patch } } : current)
  const setTaxSettings = (patch: Record<string, string | number | boolean | null>) => setDraft((current) => current ? { ...current, taxSettings: { ...current.taxSettings, ...patch } } : current)
  const patchRow = (collection: keyof FinanceAdministrationDraft, row: DraftRow, patch: Record<string, unknown>) => setDraft((current) => current ? { ...current, [collection]: (current[collection] as DraftRow[]).map((candidate) => rowKey(candidate) === rowKey(row) ? { ...candidate, ...patch } : candidate) } : current)
  const addRow = (collection: keyof FinanceAdministrationDraft, value: Record<string, unknown>) => setDraft((current) => current ? { ...current, [collection]: [...current[collection] as DraftRow[], { _key: key(), ...value }] } : current)
  const removeRow = (collection: keyof FinanceAdministrationDraft, row: DraftRow) => setDraft((current) => current ? { ...current, [collection]: row.id ? (current[collection] as DraftRow[]).map((candidate) => rowKey(candidate) === rowKey(row) ? { ...candidate, isActive: false } : candidate) : (current[collection] as DraftRow[]).filter((candidate) => rowKey(candidate) !== rowKey(row)) } : current)
  const selectEntity = (legalEntityId: string) => {
    if (!setup) return
    const nextDraft = buildDraft(setup, legalEntityId)
    setSelectedEntityId(legalEntityId); setDraft(nextDraft); baseline.current = JSON.stringify(nextDraft); setReason(""); setConfirmed(false)
    const entity = setup.legalEntities.find((item) => item.LegalEntity_ID === legalEntityId)
    setProviderForm((current) => ({ ...current, legalEntityId, externalCompany: entity?.preferredExternalCompany || "", countryCode: entity?.LegalEntity_CountryCode || nextDraft.organisation.countryCode, taxRegistrationNo: entity?.LegalEntity_VATNumber || "" }))
  }

  const save = async () => {
    if (!draft || !selectedEntityId) return
    setSaving(true)
    try {
      const result = await saveFinanceAdministration(selectedEntityId, draft, reason)
      toast.success(t(result.ready ? "Finance settings approved and ready." : "Finance settings approved with readiness items remaining."))
      setReason(""); setConfirmed(false); await load(selectedEntityId)
    } catch (cause) { toast.error(cause instanceof Error ? cause.message : t("Finance settings could not be saved.")) } finally { setSaving(false) }
  }

  const prepareProvider = async () => {
    setProviderBusy("prepare")
    try { await createFinanceConfigurationRun(providerForm); toast.success(t("Accounting connection is ready for finance approval.")); await load(selectedEntityId) } catch (cause) { toast.error(cause instanceof Error ? cause.message : t("The accounting connection review could not be prepared.")) } finally { setProviderBusy(null) }
  }
  const approveProvider = async (runId: string) => {
    setProviderBusy(runId)
    try { await approveFinanceConfigurationRun(runId); toast.success(t("Accounting connection approved.")); await load(selectedEntityId) } catch (cause) { toast.error(cause instanceof Error ? cause.message : t("The accounting connection could not be approved.")) } finally { setProviderBusy(null) }
  }
  const retryDelivery = async (queueId: string) => {
    setProviderBusy(queueId)
    try { await processFinanceIntegrationQueue(queueId); toast.success(t("Provider delivery completed.")); await load(selectedEntityId) } catch (cause) { toast.error(cause instanceof Error ? cause.message : t("Provider delivery could not be completed.")) } finally { setProviderBusy(null) }
  }

  const selectedEntity = setup?.legalEntities.find((item) => item.LegalEntity_ID === selectedEntityId)
  const checks = setup && draft ? completeness(setup, draft, selectedEntityId) : []
  const readyCount = checks.filter((item) => item.ready).length
  const latestRevision = setup?.administration.revisions.find((item) => item.FINAdminRevision_LegalEntityID === selectedEntityId && item.FINAdminRevision_StatusCode === "approved")
  const dirty = draft ? !latestRevision || JSON.stringify(draft) !== baseline.current : false
  const entityConnections = setup?.connections.filter((item) => item.ACCIC_LegalEntityID === selectedEntityId) ?? []
  const activeConnection = entityConnections.find((item) => item.ACCIC_StatusCode === "active")
  const tabs = [
    { id: "overview", label: t("Overview") }, { id: "systems", label: t("Accounting systems"), value: String(entityConnections.length) }, { id: "currencies", label: t("Currencies & FX"), value: String(draft ? activeRows(draft.currencies).length : 0) },
    { id: "banks", label: t("Bank accounts"), value: String(draft ? activeRows(draft.banks).length : 0) }, { id: "ledger", label: t("General ledger"), value: String(draft ? activeRows(draft.nominalAccounts).length : 0) }, { id: "tax", label: t("Tax"), value: String(draft ? activeRows(draft.taxCodes).length : 0) },
    { id: "documents", label: t("Documents") }, { id: "mappings", label: t("Mappings") }, { id: "compliance", label: t("Compliance") }, { id: "controls", label: t("Controls & audit") },
  ]

  if (loading || !setup || !draft) return <div className="grid min-h-72 place-items-center"><LoaderCircle className="size-5 animate-spin text-[var(--md-accent)]" /></div>

  return <>
    <SettingsPageHeader title={t("Finance administration")} description={t("Control Multideck’s native ledger, reporting, compliance foundations and optional external accounting mirrors for every legal entity.")} descriptionPlacement="under-title" icon={Landmark} actions={<div className="flex flex-wrap gap-2"><Button type="button" variant="outline" onClick={() => navigate("/finance/receivables")}>{t("Open sales ledger")}</Button><Button type="button" variant="outline" disabled={loading} onClick={() => void load(selectedEntityId)}><RefreshCw className={loading ? "animate-spin" : ""} />{t("Refresh")}</Button></div>} />
    <div className="mt-[var(--md-page-stack-gap)] space-y-[var(--md-page-stack-gap)]">
      {error ? <Notice tone="danger">{t(error)}</Notice> : null}
      {!setup.compatibility.current ? <Notice tone="danger"><div><p className="font-medium">{t("Finance service update required")}</p><p className="mt-1">{t("Deploy the latest finance migration and finance-subledger Edge Function before editing these settings.")}</p></div></Notice> : null}
      <div className="grid gap-4 rounded-[var(--md-radius-xl)] bg-[var(--md-surface-soft)] p-4 shadow-[var(--md-shadow-line)] lg:grid-cols-[minmax(260px,420px)_1fr_auto] lg:items-end">
        <SelectField id="finance-admin-entity" label={t("Legal entity")} value={selectedEntityId} onChange={selectEntity} options={setup.legalEntities.map((item) => ({ value: item.LegalEntity_ID, label: item.LegalEntity_Name }))} />
        <div className="grid grid-cols-2 gap-3 text-[12px] sm:grid-cols-4"><div><p className="text-[var(--md-subtle)]">{t("Base currency")}</p><p className="mt-1 font-medium text-[var(--md-ink)]" data-i18n-skip dir="ltr">{draft.organisation.baseCurrencyCode}</p></div><div><p className="text-[var(--md-subtle)]">{t("Country")}</p><p className="mt-1 font-medium text-[var(--md-ink)]" data-i18n-skip dir="ltr">{draft.organisation.countryCode}</p></div><div><p className="text-[var(--md-subtle)]">{t("External mirror")}</p><p className="mt-1 font-medium text-[var(--md-ink)]">{activeConnection ? setup.providers.find((item) => item.code === activeConnection.ACCIC_ProviderCode)?.name : t("Not connected")}</p></div><div><p className="text-[var(--md-subtle)]">{t("Readiness")}</p><p className="mt-1 font-medium text-[var(--md-ink)]">{readyCount}/{checks.length}</p></div></div>
        <StatusPill tone={readyCount === checks.length ? "teal" : "amber"}>{t(readyCount === checks.length ? "Ready" : "Needs setup")}</StatusPill>
      </div>
      <TabsRail tabs={tabs} activeTab={tab} onChange={(value) => { const nextTab = value as FinanceSetupTab; setTab(nextTab); if (syncFinanceRoute) navigate(financeSetupRouteByTab[nextTab]) }} />

      {tab === "overview" ? <OverviewTab setup={setup} draft={draft} entityName={selectedEntity?.LegalEntity_Name || ""} checks={checks} latestRevision={latestRevision} setOrganisation={setOrganisation} t={t} /> : null}
      {tab === "systems" ? <SystemsTab setup={setup} selectedEntityId={selectedEntityId} connections={entityConnections} companies={companies} form={providerForm} setForm={setProviderForm} busy={providerBusy} prepare={prepareProvider} approve={approveProvider} retry={retryDelivery} t={t} /> : null}
      {tab === "currencies" ? <CurrenciesTab setup={setup} draft={draft} patchRow={patchRow} addRow={addRow} removeRow={removeRow} setOrganisation={setOrganisation} setControls={setControls} t={t} /> : null}
      {tab === "banks" ? <BanksTab setup={setup} draft={draft} patchRow={patchRow} addRow={addRow} removeRow={removeRow} t={t} /> : null}
      {tab === "ledger" ? <LedgerTab setup={setup} draft={draft} patchRow={patchRow} addRow={addRow} removeRow={removeRow} setDraft={setDraft} t={t} /> : null}
      {tab === "tax" ? <TaxTab setup={setup} draft={draft} patchRow={patchRow} addRow={addRow} removeRow={removeRow} setOrganisation={setOrganisation} setTaxSettings={setTaxSettings} t={t} /> : null}
      {tab === "documents" ? <DocumentsTab setup={setup} draft={draft} patchRow={patchRow} addRow={addRow} removeRow={removeRow} setDefaults={setDefaults} t={t} /> : null}
      {tab === "mappings" ? <MappingsTab setup={setup} draft={draft} connection={activeConnection} patchRow={patchRow} addRow={addRow} removeRow={removeRow} t={t} /> : null}
      {tab === "compliance" ? <ComplianceTab setup={setup} draft={draft} selectedEntityId={selectedEntityId} t={t} /> : null}
      {tab === "controls" ? <ControlsTab setup={setup} draft={draft} selectedEntityId={selectedEntityId} setControls={setControls} t={t} /> : null}

      <SettingsPanel title={t("Approve finance settings")} description={t("Saving creates a permanent approved revision and an audit event. Use a concise reason that another finance reviewer can understand.")}>
        <div className="grid gap-4 px-5 py-4 lg:grid-cols-[1fr_auto] lg:items-end"><Field id="finance-approval-reason" label={t("Approval reason")} value={reason} onChange={setReason} placeholder={t("Initial finance setup or reviewed change reference")} /><div className="flex min-h-10 items-center gap-3"><Switch checked={confirmed} onCheckedChange={setConfirmed} aria-label={t("Confirm finance approval")} /><span className="max-w-72 text-[12px] leading-5 text-[var(--md-text)]">{t("I confirm these settings were reviewed by an authorised finance administrator.")}</span></div></div>
        <div className="flex flex-wrap items-center justify-between gap-3 px-5 py-4"><p className="text-[12px] text-[var(--md-subtle)]">{dirty ? t("Unsaved changes") : t("No unsaved changes")}{latestRevision ? ` · ${t("Current revision")} ${latestRevision.FINAdminRevision_Number}` : ""}</p><Button type="button" disabled={!dirty || !confirmed || reason.trim().length < 4 || saving || !setup.compatibility.current} onClick={() => void save()}>{saving ? <LoaderCircle className="animate-spin" /> : <Save className="size-4" />}{t("Save approved settings")}</Button></div>
      </SettingsPanel>
    </div>
  </>
}

function OverviewTab({ setup, draft, entityName, checks, latestRevision, setOrganisation, t }: { setup: FinanceSetup; draft: FinanceAdministrationDraft; entityName: string; checks: Array<{ label: string; ready: boolean }>; latestRevision: FinanceSetup["administration"]["revisions"][number] | undefined; setOrganisation: (patch: Partial<FinanceAdministrationDraft["organisation"]>) => void; t: (value: string) => string }) {
  return <div className="grid gap-[var(--md-page-stack-gap)] xl:grid-cols-[minmax(0,1.35fr)_minmax(320px,0.65fr)]"><SettingsPanel title={t("Legal entity finance profile")} description={t("These values control transaction currency, statutory treatment and financial reporting for this legal entity.")}><div className="grid gap-4 px-5 py-4 md:grid-cols-2"><Field id="finance-entity-name" label={t("Legal entity")} value={entityName} onChange={() => {}} disabled /><SelectField id="finance-country" label={t("Country")} value={draft.organisation.countryCode} onChange={(countryCode) => setOrganisation({ countryCode })} options={setup.countries.map((item) => ({ value: item.RN_Code, label: `${item.RN_Desc || item.RN_Code} · ${item.RN_Code}` }))} /><SelectField id="finance-base-currency" label={t("Base currency")} value={draft.organisation.baseCurrencyCode} onChange={(baseCurrencyCode) => setOrganisation({ baseCurrencyCode })} options={setup.currencies.map((item) => ({ value: item.Currency_Code, label: `${item.Currency_Code} · ${item.Currency_Name || item.Currency_Code}` }))} /><Field id="finance-tax-registration" label={t("Tax registration number")} value={draft.organisation.taxRegistrationNo} onChange={(taxRegistrationNo) => setOrganisation({ taxRegistrationNo })} ltr /><SelectField id="finance-reporting-basis" label={t("Reporting basis")} value={draft.organisation.reportingBasisCode} onChange={(reportingBasisCode) => setOrganisation({ reportingBasisCode })} options={[{ value: "accrual", label: t("Accrual") }, { value: "cash", label: t("Cash") }]} /><SelectField id="finance-accounting-standard" label={t("Accounting standard")} value={draft.organisation.accountingStandardCode} onChange={(accountingStandardCode) => setOrganisation({ accountingStandardCode })} options={[{ value: "IFRS", label: "IFRS" }, { value: "UK_GAAP", label: "UK GAAP" }, { value: "US_GAAP", label: "US GAAP" }, { value: "LOCAL_GAAP", label: t("Local GAAP") }]} /><SelectField id="finance-localisation-pack" label={t("Compliance pack")} value={draft.organisation.localisationPackCode} onChange={(localisationPackCode) => setOrganisation({ localisationPackCode })} options={setup.administration.localisationPacks.filter((item) => item.FINLocPack_CountryCode === draft.organisation.countryCode || item.FINLocPack_CountryCode === null).map((item) => ({ value: item.FINLocPack_Code, label: `${item.FINLocPack_Name} · v${item.FINLocPack_Version}` }))} /><SelectField id="finance-fiscal-month" label={t("Financial year starts")} value={String(draft.organisation.fiscalYearStartMonth)} onChange={(value) => setOrganisation({ fiscalYearStartMonth: Number(value) })} options={Array.from({ length: 12 }, (_, index) => ({ value: String(index + 1), label: new Intl.DateTimeFormat(undefined, { month: "long" }).format(new Date(2026, index, 1)) }))} /><Field id="finance-time-zone" label={t("Accounting time zone")} value={draft.organisation.timeZone} onChange={(timeZone) => setOrganisation({ timeZone })} ltr /></div></SettingsPanel><SettingsPanel title={t("Transaction readiness")} description={t("All areas must be ready before Multideck can process the full accounting lifecycle.")}><div className="divide-y divide-[var(--md-line)]">{checks.map((item) => <div key={item.label} className="flex items-center justify-between gap-3 px-5 py-3"><span className="text-[13px] text-[var(--md-text)]">{t(item.label)}</span><StatusPill tone={item.ready ? "teal" : "amber"}>{t(item.ready ? "Ready" : "Required")}</StatusPill></div>)}</div><div className="px-5 py-4 text-[12px] leading-5 text-[var(--md-subtle)]">{latestRevision ? <>{t("Last approved revision")} {latestRevision.FINAdminRevision_Number} · {new Intl.DateTimeFormat(undefined, { dateStyle: "medium", timeStyle: "short" }).format(new Date(latestRevision.FINAdminRevision_ApprovedAt))}</> : t("No approved finance revision yet.")}</div></SettingsPanel></div>
}

function SystemsTab({ setup, selectedEntityId, connections, companies, form, setForm, busy, prepare, approve, retry, t }: { setup: FinanceSetup; selectedEntityId: string; connections: FinanceSetup["connections"]; companies: Array<{ name: string; company_name?: string; country?: string; default_currency?: string }>; form: FinanceConfigurationInput; setForm: React.Dispatch<React.SetStateAction<FinanceConfigurationInput>>; busy: string | null; prepare: () => Promise<void>; approve: (id: string) => Promise<void>; retry: (id: string) => Promise<void>; t: (value: string) => string }) {
  const selectedProvider = setup.providers.find((item) => item.code === form.providerCode)
  const runs = setup.runs.filter((item) => item.FINConfigRun_LegalEntityID === selectedEntityId)
  return <div className="space-y-[var(--md-page-stack-gap)]"><Notice tone="success"><div><p className="font-medium">{t("Multideck remains the source of truth")}</p><p className="mt-1">{t("External accounting systems are optional mirrors. When connected, their journals and financial statements must reconcile to Multideck.")}</p></div></Notice><SettingsPanel title={t("External accounting mirrors")} description={t("Connect third-party accounting packages without transferring ownership of the operational ledger or reporting model.")}><div>{setup.providers.map((provider) => { const connection = connections.find((item) => item.ACCIC_ProviderCode === provider.code && item.ACCIC_StatusCode === "active"); return <SettingsIntegrationRow key={provider.code} icon={provider.requiresLocalAgent ? CreditCard : Link2} title={provider.name} description={provider.requiresLocalAgent ? t("Desktop mirror through a tenant-local Windows agent. Sage 50 will use the reviewed HyperExt route.") : t(`${provider.connectionModel.replaceAll("_", " ")} connector for controlled mirror exports and reconciliation.`)} status={connection ? t("Connected mirror") : provider.enabled && provider.configured ? t("Ready to connect") : t("Planned")} statusTone={connection ? "connected" : provider.enabled && provider.configured ? "ready" : "review"} /> })}</div></SettingsPanel><SettingsPanel title={t("Prepare external mirror")} description={t("A finance review checks the external company and base currency before mirroring is activated. No provider records are overwritten.")}><div className="grid gap-4 px-5 py-4 md:grid-cols-2 xl:grid-cols-4"><SelectField id="finance-provider" label={t("Provider")} value={form.providerCode} onChange={(providerCode) => setForm((current) => ({ ...current, providerCode: providerCode as AccountingProviderCode, externalCompany: "" }))} options={setup.providers.map((item) => ({ value: item.code, label: `${item.name}${item.enabled ? "" : ` · ${t("planned")}`}` }))} /><SelectField id="finance-chart-template" label={t("Chart template")} value={form.chartTemplateCode} onChange={(chartTemplateCode) => setForm((current) => ({ ...current, chartTemplateCode }))} options={setup.chartTemplates.map((item) => ({ value: item.FINChartTemplate_Code, label: item.FINChartTemplate_Name }))} />{form.providerCode === "erpnext" ? <SelectField id="finance-provider-company" label={t("ERPNext company")} value={form.externalCompany} onChange={(externalCompany) => setForm((current) => ({ ...current, externalCompany }))} options={[{ value: "", label: t("Choose company") }, ...companies.map((item) => ({ value: item.name, label: `${item.company_name || item.name}${item.default_currency ? ` · ${item.default_currency}` : ""}` }))]} disabled={!setup.erpNext.configured} /> : <Field id="finance-provider-company-disabled" label={t("Accounting company")} value="" onChange={() => {}} placeholder={t("Connector not enabled yet")} disabled />}<div className="flex items-end"><Button type="button" className="w-full" disabled={busy !== null || !selectedProvider?.enabled || !selectedProvider.configured || !form.externalCompany} onClick={() => void prepare()}>{busy === "prepare" ? <LoaderCircle className="animate-spin" /> : <ShieldCheck className="size-4" />}{t("Prepare review")}</Button></div></div>{selectedProvider?.unavailableReason ? <div className="px-5 pb-4 text-[12px] leading-5 text-[var(--md-subtle)]">{t(selectedProvider.unavailableReason)}</div> : null}</SettingsPanel>{runs.length ? <SettingsPanel title={t("Connection review history")} description={t("Every provider preflight and approval is retained.")}><div className="divide-y divide-[var(--md-line)]">{runs.map((run) => <div key={run.FINConfigRun_ID} className="flex flex-wrap items-center justify-between gap-3 px-5 py-4"><div><p className="text-[13px] font-medium text-[var(--md-ink)]">{run.FINChartTemplate?.FINChartTemplate_Name || t("Finance configuration")}</p><p className="mt-1 text-[12px] text-[var(--md-subtle)]">{run.FINConfigRun_ProviderCode} · <span>{t("External accounting company")}</span></p></div><div className="flex items-center gap-2"><StatusPill tone={run.FINConfigRun_StatusCode === "completed" ? "teal" : run.approvalBlocker ? "red" : "amber"}>{t(run.approvalBlocker ? "Needs corrected review" : run.FINConfigRun_StatusCode.replaceAll("_", " "))}</StatusPill>{run.FINConfigRun_StatusCode === "awaiting_approval" && !run.approvalBlocker ? <Button type="button" size="sm" disabled={busy !== null} onClick={() => void approve(run.FINConfigRun_ID)}>{busy === run.FINConfigRun_ID ? <LoaderCircle className="animate-spin" /> : <CircleCheck className="size-4" />}{t("Approve")}</Button> : null}</div></div>)}</div></SettingsPanel> : null}{setup.integrationQueue.length ? <SettingsPanel title={t("Mirror delivery attention")} description={t("Retry only after the named mapping or provider issue is corrected.")}><div className="divide-y divide-[var(--md-line)]">{setup.integrationQueue.map((item) => <div key={item.FINIntQ_ID} className="flex flex-wrap items-center justify-between gap-3 px-5 py-4"><div><p className="text-[13px] font-medium text-[var(--md-ink)]" data-i18n-skip>{item.localNumber}</p><p className="mt-1 max-w-3xl text-[12px] text-[var(--md-subtle)]">{t(item.FINIntQ_LastError || "Mirror delivery is waiting.")}</p></div>{item.retryAvailable ? <Button type="button" size="sm" variant="outline" disabled={busy !== null} onClick={() => void retry(item.FINIntQ_ID)}>{busy === item.FINIntQ_ID ? <LoaderCircle className="animate-spin" /> : <RefreshCw className="size-4" />}{t("Retry")}</Button> : null}</div>)}</div></SettingsPanel> : null}</div>
}

type TabEditProps = { setup: FinanceSetup; draft: FinanceAdministrationDraft; patchRow: (collection: keyof FinanceAdministrationDraft, row: DraftRow, patch: Record<string, unknown>) => void; addRow: (collection: keyof FinanceAdministrationDraft, value: Record<string, unknown>) => void; removeRow: (collection: keyof FinanceAdministrationDraft, row: DraftRow) => void; t: (value: string) => string }

function CurrenciesTab({ setup, draft, patchRow, addRow, removeRow, setOrganisation, setControls, t }: TabEditProps & { setOrganisation: (patch: Partial<FinanceAdministrationDraft["organisation"]>) => void; setControls: (patch: Record<string, string | number | boolean | null>) => void }) {
  return <div className="space-y-[var(--md-page-stack-gap)]"><SettingsPanel title={t("Operating currencies")} description={t("Choose every currency allowed on quotes and accounting documents. One base currency belongs to the legal entity.")} action={<Button type="button" size="sm" variant="outline" onClick={() => addRow("currencies", { code: "EUR", name: "Euro", decimalPlaces: 2, roundingMethodCode: "round_half_up", toleranceAmount: 0.01, permittedForQuote: true, permittedForInvoice: true, isActive: true })}><Plus className="size-4" />{t("Add currency")}</Button>}><div className="divide-y divide-[var(--md-line)]">{(draft.currencies as DraftRow[]).map((row) => <RowShell key={rowKey(row)} title={`${text(row.code, t("New currency"))} · ${text(row.name)}`} active={row.isActive !== false} onRemove={() => removeRow("currencies", row)}><div className="grid gap-4 md:grid-cols-3 xl:grid-cols-6"><SelectField id={`currency-code-${rowKey(row)}`} label={t("Currency")} value={text(row.code)} onChange={(code) => { patchRow("currencies", row, { code, name: setup.currencies.find((item) => item.Currency_Code === code)?.Currency_Name || code }); if (text(row.code) === draft.organisation.baseCurrencyCode) setOrganisation({ baseCurrencyCode: code }) }} options={setup.currencies.map((item) => ({ value: item.Currency_Code, label: `${item.Currency_Code} · ${item.Currency_Name || item.Currency_Code}` }))} /><Field id={`currency-decimals-${rowKey(row)}`} label={t("Decimal places")} value={number(row.decimalPlaces, 2)} type="number" onChange={(value) => patchRow("currencies", row, { decimalPlaces: Number(value) })} ltr /><Field id={`currency-tolerance-${rowKey(row)}`} label={t("Rounding tolerance")} value={number(row.toleranceAmount, 0.01)} type="number" onChange={(value) => patchRow("currencies", row, { toleranceAmount: Number(value) })} ltr /><div className="flex items-end justify-between gap-3 pb-2"><span className="text-[12px] text-[var(--md-text)]">{t("Quotes")}</span><Switch checked={bool(row.permittedForQuote, true)} onCheckedChange={(permittedForQuote) => patchRow("currencies", row, { permittedForQuote })} /></div><div className="flex items-end justify-between gap-3 pb-2"><span className="text-[12px] text-[var(--md-text)]">{t("Invoices")}</span><Switch checked={bool(row.permittedForInvoice, true)} onCheckedChange={(permittedForInvoice) => patchRow("currencies", row, { permittedForInvoice })} /></div><div className="flex items-end justify-between gap-3 pb-2"><span className="text-[12px] text-[var(--md-text)]">{t("Active")}</span><Switch checked={row.isActive !== false} onCheckedChange={(isActive) => patchRow("currencies", row, { isActive })} /></div></div></RowShell>)}</div></SettingsPanel><SettingsPanel title={t("Foreign exchange rules")} description={t("Multideck retains the approved rate used by every native journal. Any external mirror receives that same rate.")}><SettingsFieldRow label={t("Base currency")} description={t("Local reporting currency for this legal entity.")}><Select value={draft.organisation.baseCurrencyCode} onValueChange={(baseCurrencyCode) => setOrganisation({ baseCurrencyCode })}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{activeRows(draft.currencies).map((row) => <SelectItem key={text(row.code)} value={text(row.code)}>{text(row.code)}</SelectItem>)}</SelectContent></Select></SettingsFieldRow><SettingsFieldRow label={t("Exchange-rate source")} description={t("Choose a controlled source that remains available without an external accounting connection.")}><Select value={text(draft.controls.exchangeRateSource, "approved_manual")} onValueChange={(exchangeRateSource) => setControls({ exchangeRateSource })}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="approved_manual">{t("Approved manual rate")}</SelectItem><SelectItem value="official_source">{t("Official source")}</SelectItem><SelectItem value="accounting_provider">{t("External accounting mirror")}</SelectItem></SelectContent></Select></SettingsFieldRow><SettingsToggleRow title={t("Approve rate overrides")} description={t("Finance must approve any rate that differs from the configured source.")} checked={bool(draft.controls.exchangeRateOverrideRequiresApproval, true)} onCheckedChange={(exchangeRateOverrideRequiresApproval) => setControls({ exchangeRateOverrideRequiresApproval })} /><SettingsToggleRow title={t("Include FX in operational profit")} description={t("Include realised and unrealised exchange movement in job profitability.")} checked={bool(draft.controls.includeFxInOperationalProfit)} onCheckedChange={(includeFxInOperationalProfit) => setControls({ includeFxInOperationalProfit })} /></SettingsPanel></div>
}

function BanksTab({ setup, draft, patchRow, addRow, removeRow, t }: TabEditProps) {
  const activeCurrencies = activeRows(draft.currencies).map((row) => text(row.code)).filter(Boolean)
  const bankNominals = activeRows(draft.nominalAccounts).filter((row) => text(row.id) && (text(row.accountTypeCode).toLowerCase().includes("bank") || text(row.controlTypeCode).includes("bank")))
  return <SettingsPanel title={t("Bank accounts")} description={t("A legal entity can operate several bank accounts in several currencies. Multideck stores masked identifiers only.")} action={<Button type="button" size="sm" variant="outline" onClick={() => addRow("banks", { code: `BANK-${draft.banks.length + 1}`, name: "New bank account", currencyCode: draft.organisation.baseCurrencyCode, institutionName: "", accountHolderName: "", accountNumberLast4: "", ibanLast4: "", sortCodeLast4: "", bicLast4: "", countryCode: draft.organisation.countryCode, nominalAccountId: text(bankNominals[0]?.id), isDefault: draft.banks.length === 0, allowReceipts: true, allowPayments: true, isActive: true })}><Plus className="size-4" />{t("Add bank account")}</Button>}><div className="divide-y divide-[var(--md-line)]">{draft.banks.length ? (draft.banks as DraftRow[]).map((row) => <RowShell key={rowKey(row)} title={`${text(row.code, t("New bank"))} · ${text(row.name)}`} meta={[text(row.accountNumberMasked), text(row.ibanMasked)].filter(Boolean).join(" · ") || t("No masked identifier recorded")} active={row.isActive !== false} onRemove={() => removeRow("banks", row)}><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><Field id={`bank-code-${rowKey(row)}`} label={t("Code")} value={text(row.code)} onChange={(code) => patchRow("banks", row, { code })} ltr /><Field id={`bank-name-${rowKey(row)}`} label={t("Account name")} value={text(row.name)} onChange={(name) => patchRow("banks", row, { name })} /><Field id={`bank-institution-${rowKey(row)}`} label={t("Bank institution")} value={text(row.institutionName)} onChange={(institutionName) => patchRow("banks", row, { institutionName })} /><Field id={`bank-holder-${rowKey(row)}`} label={t("Account holder")} value={text(row.accountHolderName)} onChange={(accountHolderName) => patchRow("banks", row, { accountHolderName })} /><SelectField id={`bank-currency-${rowKey(row)}`} label={t("Currency")} value={text(row.currencyCode, draft.organisation.baseCurrencyCode)} onChange={(currencyCode) => patchRow("banks", row, { currencyCode })} options={activeCurrencies.map((code) => ({ value: code, label: code }))} /><SelectField id={`bank-country-${rowKey(row)}`} label={t("Country")} value={text(row.countryCode, draft.organisation.countryCode)} onChange={(countryCode) => patchRow("banks", row, { countryCode })} options={setup.countries.map((item) => ({ value: item.RN_Code, label: `${item.RN_Desc || item.RN_Code} · ${item.RN_Code}` }))} /><SelectField id={`bank-nominal-${rowKey(row)}`} label={t("Bank GL account")} value={text(row.nominalAccountId)} onChange={(nominalAccountId) => patchRow("banks", row, { nominalAccountId })} options={[{ value: "", label: t("Choose account") }, ...bankNominals.map((item) => ({ value: text(item.id), label: `${text(item.code)} · ${text(item.name)}` }))]} /><Field id={`bank-account-last4-${rowKey(row)}`} label={t("Account number ending")} value={text(row.accountNumberLast4)} onChange={(accountNumberLast4) => patchRow("banks", row, { accountNumberLast4: accountNumberLast4.slice(-4) })} placeholder={text(row.accountNumberMasked, "Last four only")} ltr /><Field id={`bank-iban-last4-${rowKey(row)}`} label={t("IBAN ending")} value={text(row.ibanLast4)} onChange={(ibanLast4) => patchRow("banks", row, { ibanLast4: ibanLast4.slice(-4) })} placeholder={text(row.ibanMasked, "Last four only")} ltr /><Field id={`bank-sort-last4-${rowKey(row)}`} label={t("Sort code ending")} value={text(row.sortCodeLast4)} onChange={(sortCodeLast4) => patchRow("banks", row, { sortCodeLast4: sortCodeLast4.slice(-4) })} placeholder={text(row.sortCodeMasked, "Last four only")} ltr /><Field id={`bank-bic-last4-${rowKey(row)}`} label={t("BIC ending")} value={text(row.bicLast4)} onChange={(bicLast4) => patchRow("banks", row, { bicLast4: bicLast4.slice(-4) })} placeholder={text(row.bicMasked, "Last four only")} ltr /><div className="grid grid-cols-3 gap-3 pt-6"><label className="flex items-center gap-2 text-[11px]"><Switch checked={bool(row.isDefault)} onCheckedChange={(isDefault) => patchRow("banks", row, { isDefault })} />{t("Default")}</label><label className="flex items-center gap-2 text-[11px]"><Switch checked={bool(row.allowReceipts, true)} onCheckedChange={(allowReceipts) => patchRow("banks", row, { allowReceipts })} />{t("Receipts")}</label><label className="flex items-center gap-2 text-[11px]"><Switch checked={bool(row.allowPayments, true)} onCheckedChange={(allowPayments) => patchRow("banks", row, { allowPayments })} />{t("Payments")}</label></div></div></RowShell>) : <div className="px-5 py-10 text-center"><Wallet className="mx-auto size-6 text-[var(--md-subtle)]" /><p className="mt-3 text-[13px] font-medium text-[var(--md-ink)]">{t("No bank accounts configured")}</p><p className="mt-1 text-[12px] text-[var(--md-subtle)]">{t("Add at least one bank account before posting receipts or payments.")}</p></div>}</div></SettingsPanel>
}

function LedgerTab({ setup, draft, patchRow, addRow, removeRow, setDraft, t }: TabEditProps & { setDraft: React.Dispatch<React.SetStateAction<FinanceAdministrationDraft | null>> }) {
  const loadTemplate = (templateCode: string) => setDraft((current) => { if (!current) return current; const existing = new Set(current.nominalAccounts.map((item) => text(item.code))); const additions = setup.administration.chartTemplateAccounts.filter((item) => item.FINChartTemplate?.FINChartTemplate_Code === templateCode && !existing.has(item.FINChartTemplateAccount_Code)).map((item) => ({ _key: key(), code: item.FINChartTemplateAccount_Code, name: item.FINChartTemplateAccount_Name, accountTypeCode: item.FINChartTemplateAccount_TypeCode, externalMappingHint: item.FINChartTemplateAccount_Code, isControlAccount: item.FINChartTemplateAccount_IsControlAccount, controlTypeCode: item.FINChartTemplateAccount_IsControlAccount ? item.FINChartTemplateAccount_Name.toLowerCase().replaceAll(" ", "_") : "", allowManualPosting: !item.FINChartTemplateAccount_IsControlAccount, isActive: true })); return { ...current, nominalAccounts: [...current.nominalAccounts, ...additions] } })
  return <SettingsPanel title={t("General ledger structure")} description={t("Multideck owns the reviewed chart and mappings. Existing provider accounts are never renamed or deleted automatically.")} action={<div className="flex flex-wrap gap-2"><Button type="button" size="sm" variant="outline" onClick={() => loadTemplate("generic-v1")}>{t("Add generic chart")}</Button><Button type="button" size="sm" variant="outline" onClick={() => loadTemplate("freight-forwarder-v1")}>{t("Add freight chart")}</Button><Button type="button" size="sm" variant="outline" onClick={() => addRow("nominalAccounts", { code: "", name: "", accountTypeCode: "Expense Account", externalMappingHint: "", isControlAccount: false, controlTypeCode: "", allowManualPosting: true, isActive: true })}><Plus className="size-4" />{t("Add account")}</Button></div>}><div className="divide-y divide-[var(--md-line)]">{(draft.nominalAccounts as DraftRow[]).map((row) => <RowShell key={rowKey(row)} title={`${text(row.code, t("New account"))} · ${text(row.name)}`} active={row.isActive !== false} onRemove={() => removeRow("nominalAccounts", row)}><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-6"><Field id={`nominal-code-${rowKey(row)}`} label={t("Account code")} value={text(row.code)} onChange={(code) => patchRow("nominalAccounts", row, { code })} ltr /><Field id={`nominal-name-${rowKey(row)}`} label={t("Account name")} value={text(row.name)} onChange={(name) => patchRow("nominalAccounts", row, { name })} /><SelectField id={`nominal-type-${rowKey(row)}`} label={t("Account type")} value={text(row.accountTypeCode, "Expense Account")} onChange={(accountTypeCode) => patchRow("nominalAccounts", row, { accountTypeCode })} options={["Bank", "Receivable", "Payable", "Tax", "Current Asset", "Fixed Asset", "Current Liability", "Equity", "Income Account", "Cost of Goods Sold", "Expense Account"].map((value) => ({ value, label: t(value) }))} /><Field id={`nominal-map-${rowKey(row)}`} label={t("Provider mapping hint")} value={text(row.externalMappingHint)} onChange={(externalMappingHint) => patchRow("nominalAccounts", row, { externalMappingHint })} ltr /><label className="flex items-end gap-2 pb-2 text-[12px]"><Switch checked={bool(row.isControlAccount)} onCheckedChange={(isControlAccount) => patchRow("nominalAccounts", row, { isControlAccount, allowManualPosting: isControlAccount ? false : row.allowManualPosting })} />{t("Control account")}</label><label className="flex items-end gap-2 pb-2 text-[12px]"><Switch checked={bool(row.allowManualPosting, true)} disabled={bool(row.isControlAccount)} onCheckedChange={(allowManualPosting) => patchRow("nominalAccounts", row, { allowManualPosting })} />{t("Manual posting")}</label></div></RowShell>)}</div></SettingsPanel>
}

function TaxTab({ setup, draft, patchRow, addRow, removeRow, setOrganisation, setTaxSettings, t }: TabEditProps & { setOrganisation: (patch: Partial<FinanceAdministrationDraft["organisation"]>) => void; setTaxSettings: (patch: Record<string, string | number | boolean | null>) => void }) {
  const nominals = activeRows(draft.nominalAccounts).filter((row) => text(row.id))
  const jurisdictions = activeRows(draft.taxJurisdictions)
  return <div className="space-y-[var(--md-page-stack-gap)]"><Notice tone={draft.taxSettings.localAdviceConfirmed === true ? "success" : "danger"}><div><p className="font-medium">{t("Local tax advice is required")}</p><p className="mt-1">{t("Universal treatment categories are supplied without statutory rates. An authorised finance adviser must enter, effective-date and approve the legal entity’s actual rules.")}</p></div></Notice><SettingsPanel title={t("Tax registration & jurisdiction")} description={t("Record the authority, registration and effective period for each jurisdiction.")} action={<Button type="button" size="sm" variant="outline" onClick={() => addRow("taxJurisdictions", { code: `${draft.organisation.countryCode}-TAX`, name: "Tax jurisdiction", countryCode: draft.organisation.countryCode, authorityName: "", registrationNo: draft.organisation.taxRegistrationNo, effectiveFrom: today(), effectiveTo: "", isActive: true })}><Plus className="size-4" />{t("Add jurisdiction")}</Button>}><div className="grid gap-4 px-5 py-4 md:grid-cols-2"><Field id="tax-registration-main" label={t("Primary tax registration")} value={draft.organisation.taxRegistrationNo} onChange={(taxRegistrationNo) => setOrganisation({ taxRegistrationNo })} ltr /><SelectField id="tax-reporting-basis" label={t("Reporting basis")} value={draft.organisation.reportingBasisCode} onChange={(reportingBasisCode) => setOrganisation({ reportingBasisCode })} options={[{ value: "accrual", label: t("Accrual") }, { value: "cash", label: t("Cash") }]} /></div><div className="divide-y divide-[var(--md-line)]">{(draft.taxJurisdictions as DraftRow[]).map((row) => <RowShell key={rowKey(row)} title={`${text(row.code)} · ${text(row.name)}`} active={row.isActive !== false} onRemove={() => removeRow("taxJurisdictions", row)}><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-5"><Field id={`jur-code-${rowKey(row)}`} label={t("Code")} value={text(row.code)} onChange={(code) => patchRow("taxJurisdictions", row, { code })} ltr /><Field id={`jur-name-${rowKey(row)}`} label={t("Name")} value={text(row.name)} onChange={(name) => patchRow("taxJurisdictions", row, { name })} /><Field id={`jur-authority-${rowKey(row)}`} label={t("Tax authority")} value={text(row.authorityName)} onChange={(authorityName) => patchRow("taxJurisdictions", row, { authorityName })} /><Field id={`jur-registration-${rowKey(row)}`} label={t("Registration number")} value={text(row.registrationNo)} onChange={(registrationNo) => patchRow("taxJurisdictions", row, { registrationNo })} ltr /><Field id={`jur-effective-${rowKey(row)}`} label={t("Effective from")} value={text(row.effectiveFrom, today())} type="date" onChange={(effectiveFrom) => patchRow("taxJurisdictions", row, { effectiveFrom })} ltr /></div></RowShell>)}</div></SettingsPanel><SettingsPanel title={t("Tax treatments")} description={t("Operators can select only these approved treatments; they cannot type tax rates or arbitrary provider templates.")} action={<Button type="button" size="sm" variant="outline" onClick={() => addRow("taxCodes", { code: "", name: "", countryCode: draft.organisation.countryCode, ratePercent: 0, taxTypeCode: "vat", providerMappingHint: "", isRecoverable: true, isActive: true, effectiveFrom: today(), effectiveTo: "", jurisdictionId: text(jurisdictions[0]?.id), treatmentCategoryCode: "domestic_standard", transactionTypeCode: "both", outputNominalId: "", inputNominalId: "" })}><Plus className="size-4" />{t("Add treatment")}</Button>}><div className="divide-y divide-[var(--md-line)]">{(draft.taxCodes as DraftRow[]).map((row) => <RowShell key={rowKey(row)} title={`${text(row.code, t("New treatment"))} · ${text(row.name)}`} active={row.isActive !== false} onRemove={() => removeRow("taxCodes", row)}><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-7"><Field id={`tax-code-${rowKey(row)}`} label={t("Code")} value={text(row.code)} onChange={(code) => patchRow("taxCodes", row, { code })} ltr /><Field id={`tax-name-${rowKey(row)}`} label={t("Name")} value={text(row.name)} onChange={(name) => patchRow("taxCodes", row, { name })} /><Field id={`tax-rate-${rowKey(row)}`} label={t("Rate %")} value={number(row.ratePercent)} type="number" onChange={(ratePercent) => patchRow("taxCodes", row, { ratePercent: Number(ratePercent) })} ltr /><SelectField id={`tax-transaction-${rowKey(row)}`} label={t("Applies to")} value={text(row.transactionTypeCode, "both")} onChange={(transactionTypeCode) => patchRow("taxCodes", row, { transactionTypeCode })} options={[{ value: "both", label: t("Sales & purchases") }, { value: "sales", label: t("Sales") }, { value: "purchase", label: t("Purchases") }]} /><SelectField id={`tax-output-${rowKey(row)}`} label={t("Output tax account")} value={text(row.outputNominalId)} onChange={(outputNominalId) => patchRow("taxCodes", row, { outputNominalId })} options={[{ value: "", label: t("Choose account") }, ...nominals.map((item) => ({ value: text(item.id), label: `${text(item.code)} · ${text(item.name)}` }))]} /><SelectField id={`tax-input-${rowKey(row)}`} label={t("Input tax account")} value={text(row.inputNominalId)} onChange={(inputNominalId) => patchRow("taxCodes", row, { inputNominalId })} options={[{ value: "", label: t("Choose account") }, ...nominals.map((item) => ({ value: text(item.id), label: `${text(item.code)} · ${text(item.name)}` }))]} /><label className="flex items-end gap-2 pb-2 text-[12px]"><Switch checked={bool(row.isRecoverable, true)} onCheckedChange={(isRecoverable) => patchRow("taxCodes", row, { isRecoverable })} />{t("Recoverable")}</label></div></RowShell>)}</div></SettingsPanel><SettingsPanel title={t("Tax calculation rules")} description={t("These rules govern document tax calculation before the approved transaction posts to the Multideck ledger and any configured mirror.")}><SettingsToggleRow title={t("Prices include tax")} description={t("Treat entered line amounts as tax-inclusive.")} checked={bool(draft.taxSettings.priceIncludesTax)} onCheckedChange={(priceIncludesTax) => setTaxSettings({ priceIncludesTax })} /><SettingsToggleRow title={t("Enable reverse charge")} description={t("Allow approved reverse-charge treatments where local rules require them.")} checked={bool(draft.taxSettings.reverseChargeEnabled, true)} onCheckedChange={(reverseChargeEnabled) => setTaxSettings({ reverseChargeEnabled })} /><SettingsToggleRow title={t("Local advice confirmed")} description={t("An authorised finance adviser has reviewed the rates, accounts and effective dates.")} checked={bool(draft.taxSettings.localAdviceConfirmed)} onCheckedChange={(localAdviceConfirmed) => setTaxSettings({ localAdviceConfirmed })} /></SettingsPanel></div>
}

function DocumentsTab({ setup, draft, patchRow, addRow, removeRow, setDefaults, t }: TabEditProps & { setDefaults: (patch: Record<string, string | number | boolean | null>) => void }) {
  const terms = activeRows(draft.paymentTerms)
  const sequences = activeRows(draft.numberSequences)
  return <div className="space-y-[var(--md-page-stack-gap)]"><SettingsPanel title={t("Payment terms")} description={t("Reusable customer and supplier due-date rules.")} action={<Button type="button" size="sm" variant="outline" onClick={() => addRow("paymentTerms", { code: "", name: "", days: 30, dueDayOfMonth: "", endOfMonth: false, isCashAccount: false, isActive: true })}><Plus className="size-4" />{t("Add terms")}</Button>}><div className="divide-y divide-[var(--md-line)]">{(draft.paymentTerms as DraftRow[]).map((row) => <RowShell key={rowKey(row)} title={`${text(row.code, t("New terms"))} · ${text(row.name)}`} active={row.isActive !== false} onRemove={() => removeRow("paymentTerms", row)}><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-5"><Field id={`term-code-${rowKey(row)}`} label={t("Code")} value={text(row.code)} onChange={(code) => patchRow("paymentTerms", row, { code })} ltr /><Field id={`term-name-${rowKey(row)}`} label={t("Name")} value={text(row.name)} onChange={(name) => patchRow("paymentTerms", row, { name })} /><Field id={`term-days-${rowKey(row)}`} label={t("Days")} value={number(row.days, 30)} type="number" onChange={(days) => patchRow("paymentTerms", row, { days: Number(days) })} ltr /><label className="flex items-end gap-2 pb-2 text-[12px]"><Switch checked={bool(row.endOfMonth)} onCheckedChange={(endOfMonth) => patchRow("paymentTerms", row, { endOfMonth })} />{t("End of month")}</label><label className="flex items-end gap-2 pb-2 text-[12px]"><Switch checked={bool(row.isCashAccount)} onCheckedChange={(isCashAccount) => patchRow("paymentTerms", row, { isCashAccount })} />{t("Due immediately")}</label></div></RowShell>)}</div></SettingsPanel><SettingsPanel title={t("Document numbering")} description={t("Prefixes, padding and next numbers are controlled independently for each legal entity.")} action={<Button type="button" size="sm" variant="outline" onClick={() => addRow("numberSequences", { code: "", name: "", documentTypeCode: "sl_invoice", prefix: "", suffix: "", nextNumber: 1, paddingLength: 6, resetPeriodCode: "never", isActive: true })}><Plus className="size-4" />{t("Add sequence")}</Button>}><div className="divide-y divide-[var(--md-line)]">{(draft.numberSequences as DraftRow[]).map((row) => <RowShell key={rowKey(row)} title={`${text(row.code, t("New sequence"))} · ${text(row.name)}`} active={row.isActive !== false} onRemove={() => removeRow("numberSequences", row)}><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-7"><Field id={`sequence-code-${rowKey(row)}`} label={t("Code")} value={text(row.code)} onChange={(code) => patchRow("numberSequences", row, { code })} ltr /><SelectField id={`sequence-type-${rowKey(row)}`} label={t("Document type")} value={text(row.documentTypeCode)} onChange={(documentTypeCode) => patchRow("numberSequences", row, { documentTypeCode })} options={setup.administration.documentTypes.map((item) => ({ value: item.FINDT_Code, label: t(item.FINDT_Name) }))} /><Field id={`sequence-prefix-${rowKey(row)}`} label={t("Prefix")} value={text(row.prefix)} onChange={(prefix) => patchRow("numberSequences", row, { prefix })} ltr /><Field id={`sequence-suffix-${rowKey(row)}`} label={t("Suffix")} value={text(row.suffix)} onChange={(suffix) => patchRow("numberSequences", row, { suffix })} ltr /><Field id={`sequence-next-${rowKey(row)}`} label={t("Next number")} value={number(row.nextNumber, 1)} type="number" onChange={(nextNumber) => patchRow("numberSequences", row, { nextNumber: Number(nextNumber) })} ltr /><Field id={`sequence-padding-${rowKey(row)}`} label={t("Padding")} value={number(row.paddingLength, 6)} type="number" onChange={(paddingLength) => patchRow("numberSequences", row, { paddingLength: Number(paddingLength) })} ltr /><SelectField id={`sequence-reset-${rowKey(row)}`} label={t("Reset")} value={text(row.resetPeriodCode, "never")} onChange={(resetPeriodCode) => patchRow("numberSequences", row, { resetPeriodCode })} options={[{ value: "never", label: t("Never") }, { value: "yearly", label: t("Yearly") }, { value: "monthly", label: t("Monthly") }]} /></div></RowShell>)}</div></SettingsPanel><SettingsPanel title={t("Document defaults")} description={t("Defaults reduce operator entry without allowing arbitrary accounts or tax rules.")}><div className="grid gap-4 px-5 py-4 md:grid-cols-2 xl:grid-cols-4"><SelectField id="default-sales-term" label={t("Sales payment terms")} value={text(draft.defaults.salesPaymentTermCode, "NET30")} onChange={(salesPaymentTermCode) => setDefaults({ salesPaymentTermCode })} options={terms.map((item) => ({ value: text(item.code), label: `${text(item.code)} · ${text(item.name)}` }))} /><SelectField id="default-purchase-term" label={t("Purchase payment terms")} value={text(draft.defaults.purchasePaymentTermCode, "NET30")} onChange={(purchasePaymentTermCode) => setDefaults({ purchasePaymentTermCode })} options={terms.map((item) => ({ value: text(item.code), label: `${text(item.code)} · ${text(item.name)}` }))} /><SelectField id="default-sales-sequence" label={t("Sales invoice sequence")} value={text(draft.defaults.salesInvoiceSequenceCode, "sales-invoice")} onChange={(salesInvoiceSequenceCode) => setDefaults({ salesInvoiceSequenceCode })} options={sequences.filter((item) => item.documentTypeCode === "sl_invoice").map((item) => ({ value: text(item.code), label: text(item.name) }))} /><SelectField id="default-purchase-sequence" label={t("Purchase invoice sequence")} value={text(draft.defaults.purchaseInvoiceSequenceCode, "purchase-invoice")} onChange={(purchaseInvoiceSequenceCode) => setDefaults({ purchaseInvoiceSequenceCode })} options={sequences.filter((item) => item.documentTypeCode === "pl_invoice").map((item) => ({ value: text(item.code), label: text(item.name) }))} /></div></SettingsPanel></div>
}

function MappingsTab({ draft, connection, patchRow, addRow, removeRow, t }: TabEditProps & { connection: FinanceSetup["connections"][number] | undefined }) {
  if (!connection) return <Notice><div><p className="font-medium">{t("No external mirror connected")}</p><p className="mt-1">{t("Multideck accounting continues normally. Provider account, charge and tax mappings become available when an external mirror is connected.")}</p></div></Notice>
  return <div className="space-y-[var(--md-page-stack-gap)]"><Notice><div><p className="font-medium">{t("Active mapping target")}</p><p className="mt-1">{connection.ACCIC_Name}</p></div></Notice><MappingPanel title={t("Control-account mappings")} description={t("Map Multideck contexts such as receivables, payables, bank and tax controls to provider GL accounts.")} collection="accountMappings" rows={draft.accountMappings as DraftRow[]} add={() => addRow("accountMappings", { connectionId: connection.ACCIC_ID, directionCode: "sales", localContextCode: "receivables_control", providerAccountId: "", providerAccountCode: "", providerAccountName: "", isDefault: false, isActive: true })} patchRow={patchRow} removeRow={removeRow} render={(row) => <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-5"><SelectField id={`map-direction-${rowKey(row)}`} label={t("Direction")} value={text(row.directionCode, "sales")} onChange={(directionCode) => patchRow("accountMappings", row, { directionCode })} options={[{ value: "sales", label: t("Sales") }, { value: "purchase", label: t("Purchases") }]} /><Field id={`map-context-${rowKey(row)}`} label={t("Multideck context")} value={text(row.localContextCode)} onChange={(localContextCode) => patchRow("accountMappings", row, { localContextCode })} ltr /><Field id={`map-account-code-${rowKey(row)}`} label={t("Provider account code")} value={text(row.providerAccountCode)} onChange={(providerAccountCode) => patchRow("accountMappings", row, { providerAccountCode, providerAccountId: text(row.providerAccountId) || providerAccountCode })} ltr /><Field id={`map-account-name-${rowKey(row)}`} label={t("Provider account name")} value={text(row.providerAccountName)} onChange={(providerAccountName) => patchRow("accountMappings", row, { providerAccountName })} /><label className="flex items-end gap-2 pb-2 text-[12px]"><Switch checked={bool(row.isDefault)} onCheckedChange={(isDefault) => patchRow("accountMappings", row, { isDefault })} />{t("Default")}</label></div>} t={t} /><MappingPanel title={t("Charge-code mappings")} description={t("Map freight charge codes to controlled provider service items and income or cost accounts.")} collection="chargeMappings" rows={draft.chargeMappings as DraftRow[]} add={() => addRow("chargeMappings", { connectionId: connection.ACCIC_ID, directionCode: "sales", localChargeCode: "ADHOC", providerItemId: "", providerItemCode: "", providerItemName: "", providerAccountId: "", isActive: true })} patchRow={patchRow} removeRow={removeRow} render={(row) => <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-5"><SelectField id={`charge-direction-${rowKey(row)}`} label={t("Direction")} value={text(row.directionCode, "sales")} onChange={(directionCode) => patchRow("chargeMappings", row, { directionCode })} options={[{ value: "sales", label: t("Sales") }, { value: "purchase", label: t("Purchases") }]} /><Field id={`charge-local-${rowKey(row)}`} label={t("Charge code")} value={text(row.localChargeCode)} onChange={(localChargeCode) => patchRow("chargeMappings", row, { localChargeCode })} ltr /><Field id={`charge-item-${rowKey(row)}`} label={t("Provider item code")} value={text(row.providerItemCode)} onChange={(providerItemCode) => patchRow("chargeMappings", row, { providerItemCode })} ltr /><Field id={`charge-item-name-${rowKey(row)}`} label={t("Provider item name")} value={text(row.providerItemName)} onChange={(providerItemName) => patchRow("chargeMappings", row, { providerItemName })} /><Field id={`charge-account-${rowKey(row)}`} label={t("Provider account ID")} value={text(row.providerAccountId)} onChange={(providerAccountId) => patchRow("chargeMappings", row, { providerAccountId })} ltr /></div>} t={t} /><MappingPanel title={t("Tax mappings")} description={t("Map approved Multideck tax treatments to provider tax templates or codes by direction.")} collection="taxMappings" rows={draft.taxMappings as DraftRow[]} add={() => addRow("taxMappings", { connectionId: connection.ACCIC_ID, directionCode: "sales", localTaxCode: "domestic-standard", localTaxDescription: "Domestic standard", countryCode: draft.organisation.countryCode, providerTaxId: "", providerTaxCode: "", providerTaxName: "", taxRatePercent: "", isActive: true })} patchRow={patchRow} removeRow={removeRow} render={(row) => <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-5"><SelectField id={`taxmap-direction-${rowKey(row)}`} label={t("Direction")} value={text(row.directionCode, "sales")} onChange={(directionCode) => patchRow("taxMappings", row, { directionCode })} options={[{ value: "sales", label: t("Sales") }, { value: "purchase", label: t("Purchases") }]} /><SelectField id={`taxmap-local-${rowKey(row)}`} label={t("Tax treatment")} value={text(row.localTaxCode)} onChange={(localTaxCode) => patchRow("taxMappings", row, { localTaxCode })} options={activeRows(draft.taxCodes).map((item) => ({ value: text(item.code), label: `${text(item.code)} · ${text(item.name)}` }))} /><Field id={`taxmap-provider-${rowKey(row)}`} label={t("Provider tax code")} value={text(row.providerTaxCode)} onChange={(providerTaxCode) => patchRow("taxMappings", row, { providerTaxCode })} ltr /><Field id={`taxmap-name-${rowKey(row)}`} label={t("Provider tax name")} value={text(row.providerTaxName)} onChange={(providerTaxName) => patchRow("taxMappings", row, { providerTaxName })} /><Field id={`taxmap-rate-${rowKey(row)}`} label={t("Provider rate %")} value={text(row.taxRatePercent)} type="number" onChange={(taxRatePercent) => patchRow("taxMappings", row, { taxRatePercent })} ltr /></div>} t={t} /></div>
}

function MappingPanel({ title, description, collection, rows, add, patchRow, removeRow, render, t }: { title: string; description: string; collection: "accountMappings" | "chargeMappings" | "taxMappings"; rows: DraftRow[]; add: () => void; patchRow: TabEditProps["patchRow"]; removeRow: TabEditProps["removeRow"]; render: (row: DraftRow) => ReactNode; t: (value: string) => string }) {
  return <SettingsPanel title={title} description={description} action={<Button type="button" size="sm" variant="outline" onClick={add}><Plus className="size-4" />{t("Add mapping")}</Button>}><div className="divide-y divide-[var(--md-line)]">{rows.length ? rows.map((row) => <RowShell key={rowKey(row)} title={text(row.localContextCode || row.localChargeCode || row.localTaxCode, t("New mapping"))} active={row.isActive !== false} onRemove={() => removeRow(collection, row)}>{render(row)}</RowShell>) : <div className="px-5 py-8 text-center text-[12px] text-[var(--md-subtle)]">{t("No mappings configured yet.")}</div>}</div></SettingsPanel>
}

function ComplianceTab({ setup, draft, selectedEntityId, t }: { setup: FinanceSetup; draft: FinanceAdministrationDraft; selectedEntityId: string; t: (value: string) => string }) {
  const entity = setup.legalEntities.find((item) => item.LegalEntity_ID === selectedEntityId)
  const pack = setup.administration.localisationPacks.find((item) => item.FINLocPack_Code === draft.organisation.localisationPackCode)
    ?? setup.administration.localisationPacks.find((item) => item.FINLocPack_CountryCode === entity?.LegalEntity_CountryCode)
  const obligations = pack ? setup.administration.complianceObligations.filter((item) => item.FINCompliance_PackID === pack.FINLocPack_ID) : []
  const registrationFor = (obligationId: string) => setup.administration.complianceRegistrations.find((item) => item.FINComplianceReg_LegalEntityID === selectedEntityId && item.FINComplianceReg_ObligationID === obligationId)

  return <div className="space-y-[var(--md-page-stack-gap)]">
    <Notice><div><p className="font-medium">{t("Compliance foundation, not filing certification")}</p><p className="mt-1">{t("These packs define ledger, tax and reporting requirements. Direct authority filing stays disabled until Multideck has completed each authority’s software approval, security testing and production access requirements.")}</p></div></Notice>
    <Notice tone="success"><div><p className="font-medium">{t("Payroll is outside this finance scope")}</p><p className="mt-1">{t("Payroll calculations, submissions and employment-tax reporting are not included in this accounting system.")}</p></div></Notice>
    <SettingsPanel title={t("Jurisdiction pack")} description={t("The pack determines the accounting standard and authority obligations shown for this legal entity.")}>
      {pack ? <div className="grid gap-4 px-5 py-4 sm:grid-cols-2 xl:grid-cols-4"><div><p className="text-[11px] text-[var(--md-subtle)]">{t("Pack")}</p><p className="mt-1 text-[13px] font-medium text-[var(--md-ink)]">{pack.FINLocPack_Name}</p></div><div><p className="text-[11px] text-[var(--md-subtle)]">{t("Accounting standard")}</p><p className="mt-1 text-[13px] font-medium text-[var(--md-ink)]" data-i18n-skip dir="ltr">{pack.FINLocPack_AccountingStandardCode || t("Local standard")}</p></div><div><p className="text-[11px] text-[var(--md-subtle)]">{t("Authority")}</p><p className="mt-1 text-[13px] font-medium text-[var(--md-ink)]">{pack.FINLocPack_AuthorityName || t("Jurisdiction authorities")}</p></div><div><p className="text-[11px] text-[var(--md-subtle)]">{t("Pack status")}</p><div className="mt-1"><StatusPill tone={pack.FINLocPack_ComplianceStatusCode === "production_ready" ? "teal" : "amber"}>{t(pack.FINLocPack_ComplianceStatusCode.replaceAll("_", " "))}</StatusPill></div></div></div> : <div className="px-5 py-8 text-center text-[12px] text-[var(--md-subtle)]">{t("Choose a supported compliance pack in Overview.")}</div>}
    </SettingsPanel>
    <SettingsPanel title={t("Compliance obligations")} description={t("Current requirements for this jurisdiction, their filing channel and production readiness.")}>
      <div className="divide-y divide-[var(--md-line)]">{obligations.length ? obligations.map((obligation) => {
        const registration = registrationFor(obligation.FINCompliance_ID)
        const requirement = asRecord(obligation.FINCompliance_RequirementsJSON)
        return <div key={obligation.FINCompliance_ID} className="px-5 py-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-[13px] font-medium text-[var(--md-ink)]">{t(obligation.FINCompliance_Name)}</p><p className="mt-1 text-[12px] text-[var(--md-subtle)]">{t(obligation.FINCompliance_AuthorityName)} · {t(obligation.FINCompliance_FrequencyCode)} · {t(obligation.FINCompliance_FilingChannelCode.replaceAll("_", " "))}</p></div><div className="flex flex-wrap gap-2"><StatusPill tone={obligation.FINCompliance_ReadinessStatusCode === "production_ready" ? "teal" : "amber"}>{t(obligation.FINCompliance_ReadinessStatusCode.replaceAll("_", " "))}</StatusPill><StatusPill tone={registration?.FINComplianceReg_StatusCode === "production_verified" ? "teal" : "neutral"}>{t(registration?.FINComplianceReg_StatusCode || "not registered")}</StatusPill></div></div>{typeof requirement.productionGate === "string" ? <p className="mt-3 text-[12px] leading-5 text-[var(--md-text)]"><span className="font-medium">{t("Production gate")}:</span> {t(requirement.productionGate)}</p> : null}<a className="mt-3 inline-flex text-[12px] font-medium text-[var(--md-accent)] hover:underline" href={obligation.FINCompliance_SourceURL} target="_blank" rel="noreferrer">{t("Open authority guidance")}</a></div>
      }) : <div className="px-5 py-8 text-center text-[12px] text-[var(--md-subtle)]">{t("No obligations are defined for this pack yet.")}</div>}</div>
    </SettingsPanel>
  </div>
}

function ControlsTab({ setup, draft, selectedEntityId, setControls, t }: { setup: FinanceSetup; draft: FinanceAdministrationDraft; selectedEntityId: string; setControls: (patch: Record<string, string | number | boolean | null>) => void; t: (value: string) => string }) {
  const revisions = setup.administration.revisions.filter((item) => item.FINAdminRevision_LegalEntityID === selectedEntityId)
  return <div className="space-y-[var(--md-page-stack-gap)]"><SettingsPanel title={t("Ledger ownership & mirror policy")} description={t("Multideck is the canonical ledger. A third-party accounting package may be disabled, optional or required as a reconciled mirror.")}><SettingsFieldRow label={t("Native Multideck ledger")} description={t("All approved finance documents and cash transactions post here first.")}><StatusPill tone="teal">{t("Enabled")}</StatusPill></SettingsFieldRow><SettingsFieldRow label={t("External accounting mirror")} description={t("Required blocks a ready finance configuration until an active third-party connection exists.")}><Select value={text(draft.controls.externalMirrorModeCode, "optional")} onValueChange={(externalMirrorModeCode) => setControls({ externalMirrorModeCode })}><SelectTrigger className="w-full sm:w-48"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="disabled">{t("Disabled")}</SelectItem><SelectItem value="optional">{t("Optional")}</SelectItem><SelectItem value="required">{t("Required")}</SelectItem></SelectContent></Select></SettingsFieldRow></SettingsPanel><SettingsPanel title={t("Posting & approval controls")} description={t("Operations prepare drafts. Finance controls configuration, approval and native posting.")}><SettingsToggleRow title={t("Require finance review")} description={t("Every invoice, credit, receipt and payment requires finance approval before native posting and any configured mirror delivery.")} checked={bool(draft.controls.requireFinanceReview, true)} onCheckedChange={(requireFinanceReview) => setControls({ requireFinanceReview })} /><SettingsToggleRow title={t("Auto-create sales invoice drafts")} description={t("Create draft sales invoices from approved operational billing events.")} checked={bool(draft.controls.autoCreateSalesInvoices)} onCheckedChange={(autoCreateSalesInvoices) => setControls({ autoCreateSalesInvoices })} /><SettingsToggleRow title={t("Auto-create purchase accruals")} description={t("Prepare purchase accrual drafts from approved supplier costs.")} checked={bool(draft.controls.autoCreatePurchaseAccruals, true)} onCheckedChange={(autoCreatePurchaseAccruals) => setControls({ autoCreatePurchaseAccruals })} /><SettingsToggleRow title={t("Auto-post low-risk items")} description={t("Keep disabled until the risk policy and approval limits have been tested.")} checked={bool(draft.controls.autoPostLowRiskItems)} onCheckedChange={(autoPostLowRiskItems) => setControls({ autoPostLowRiskItems })} /><SettingsToggleRow title={t("Block locked-period posting")} description={t("Prevent direct posting into closed or locked accounting periods.")} checked={bool(draft.controls.blockLockedPeriodDirectPosting, true)} onCheckedChange={(blockLockedPeriodDirectPosting) => setControls({ blockLockedPeriodDirectPosting })} /><SettingsToggleRow title={t("Allow operator tax override")} description={t("When disabled, operators can select approved treatments only.")} checked={bool(draft.controls.allowOperatorTaxOverride)} onCheckedChange={(allowOperatorTaxOverride) => setControls({ allowOperatorTaxOverride })} /><SettingsToggleRow title={t("Allow operator GL override")} description={t("When disabled, charge-code rules determine the nominal account.")} checked={bool(draft.controls.allowOperatorAccountOverride)} onCheckedChange={(allowOperatorAccountOverride) => setControls({ allowOperatorAccountOverride })} /><SettingsFieldRow label={t("Posting lock date")} description={t("Transactions dated on or before this date cannot be posted directly.")}><Input type="date" value={text(draft.controls.postingLockDate)} onChange={(event) => setControls({ postingLockDate: event.target.value })} data-i18n-skip dir="ltr" /></SettingsFieldRow><SettingsFieldRow label={t("Allocation tolerance")} description={t("Maximum permitted cash allocation difference.")}><Input type="number" step="0.01" min="0" value={number(draft.controls.allocationTolerance, 0.01)} onChange={(event) => setControls({ allocationTolerance: Number(event.target.value) })} data-i18n-skip dir="ltr" /></SettingsFieldRow></SettingsPanel><SettingsPanel title={t("Approved revision history")} description={t("Settings are immutable evidence; later approvals supersede rather than erase earlier revisions.")}><div className="divide-y divide-[var(--md-line)]">{revisions.length ? revisions.map((revision) => <div key={revision.FINAdminRevision_ID} className="flex flex-wrap items-center justify-between gap-3 px-5 py-4"><div><p className="text-[13px] font-medium text-[var(--md-ink)]">{t("Revision")} {revision.FINAdminRevision_Number}</p><p className="mt-1 text-[12px] text-[var(--md-subtle)]">{revision.FINAdminRevision_Reason || t("No approval reason recorded")} · {new Intl.DateTimeFormat(undefined, { dateStyle: "medium", timeStyle: "short" }).format(new Date(revision.FINAdminRevision_ApprovedAt))}</p></div><StatusPill tone={revision.FINAdminRevision_StatusCode === "approved" ? "teal" : "neutral"}>{t(revision.FINAdminRevision_StatusCode)}</StatusPill></div>) : <div className="px-5 py-8 text-center text-[12px] text-[var(--md-subtle)]">{t("No approved revisions yet.")}</div>}</div></SettingsPanel></div>
}
